:root {
  color-scheme: light dark;
  --ink: #1a1a1a;
  --paper: #fdfcf9;
  --muted: #5b5b5b;
  --border: #d9d5cc;
  --accent: #0f766e;
  --accent-ink: #ffffff;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  line-height: 1.5;
}

#app {
  max-width: 640px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

h1 {
  margin-bottom: 0.1rem;
}

.tagline {
  color: var(--muted);
  margin-top: 0;
}

.field {
  margin-bottom: 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

input[type="text"],
input[type="search"],
textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: white;
  color: var(--ink);
}

textarea {
  resize: vertical;
}

.hint {
  margin: 0.1rem 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.hint code {
  background: rgba(0, 0, 0, 0.06);
  padding: 0 0.25em;
  border-radius: 3px;
}

button[type="submit"] {
  font: inherit;
  font-weight: 600;
  padding: 0.55rem 1.1rem;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: var(--accent-ink);
  cursor: pointer;
}

button[type="submit"]:hover {
  filter: brightness(1.08);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.search-wrap {
  margin-top: 2rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

#results-line {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
  min-height: 1.1em;
}

#feed {
  margin-top: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.note {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.9rem 1rem;
  background: white;
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 0.7rem;
  row-gap: 0.3rem;
}

.note[aria-current="true"] {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.note-avatar {
  grid-row: 1 / span 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
}

.note:not(:has(.note-avatar)) .note-title,
.note:not(:has(.note-avatar)) .note-body {
  grid-column: 1 / -1;
}

.note-title {
  grid-column: 2;
  font: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  text-align: left;
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  cursor: pointer;
  color: var(--ink);
  text-decoration: underline;
  text-decoration-color: transparent;
}

.note-title:hover {
  text-decoration-color: var(--accent);
}

.note-body {
  grid-column: 2;
  font-size: 0.95rem;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.empty-state {
  color: var(--muted);
  font-style: italic;
}

