const firstTitle = await page.$eval('#feed article.note:first-child .note-title', el => el.textContent);
console.log('newest note title (should be plain, no bold):', JSON.stringify(firstTitle));
const boldExists = await page.$('#feed article.note:first-child .note-body b');
console.log('body has <b>:', !!boldExists);
const linkHref = await page.$eval('#feed article.note:first-child .note-body a', el => el.getAttribute('href')).catch(() => null);
console.log('link href:', linkHref);
const brCount = await page.$$eval('#feed article.note:first-child .note-body br', els => els.length);
console.log('br count (line break from \\n):', brCount);

// form cleared?
const titleVal = await page.$eval('#title', el => el.value);
console.log('title input cleared:', titleVal === '');

// 3. search
await page.fill('#search', 'Douro');
await page.waitForTimeout(100);
const resultsText = await page.$eval('#results-line', el => el.textContent);
console.log('results-line:', JSON.stringify(resultsText));
const visibleCount = await page.$$eval('#feed article.note', els => els.length);
console.log('visible after search Douro:', visibleCount);
const hash1 = await page.evaluate(() => location.hash);
