await page.reload();
await page.waitForTimeout(200);
const searchValAfterReload = await page.$eval('#search', el => el.value);
const ariaCurrentAfterReload = await page.$eval('#feed article.note:first-child', el => el.getAttribute('aria-current')).catch(() => null);
console.log('search restored after reload:', searchValAfterReload);
console.log('aria-current restored after reload:', ariaCurrentAfterReload);

// 6. XSS check - script tag / onerror should not execute or appear
await page.fill('#search', '');
await page.evaluate(() => { location.hash = ''; });
await page.fill('#title', 'xss test');
await page.fill('#body', '<img src=x onerror="window.__xss=true"><script>window.__xss2=true</script>');
